for path in ['/api/score-history','/history.js','/']:
    try:
        r=httpx.get(url+path,headers={'Authorization':'Bearer '+v['LAB_UPLOAD_TOKEN']} if path.startswith('/api/') else {},timeout=15)
        r.raise_for_status()
        if path.startswith('/api/'):
            print(json.dumps({'path':path,'status':r.status_code,'points':len(r.json()['points'])}),flush=True)
        else:
            assert ('globalThis.ScoreHistory' if path.endswith('.js') else 'id="nav-history"') in r.text
            print(json.dumps({'path':path,'status':r.status_code,'new_feature_present':True}),flush=True)
    except httpx.HTTPError as exc:
        print(json.dumps({'path':path,'error_type':type(exc).__name__}),flush=True)
PY

